tool_input.command:
Set-Location D:\nginx
Write-Host "=== nginx -t ==="
& .\nginx.exe -t 2>&1 | ForEach-Object { if($_ -is [System.Management.Automation.ErrorRecord]){ $_.Exception.Message } else { $_ } }
Write-Host "=== reload ==="
& .\nginx.exe -s reload 2>&1 | Out-Null; Write-Host "reload rc=$LASTEXITCODE"

$new='D:\repository\门户H5\dist\index.html'
$old='D:\repository\门户\dist\index.html'
function Check($port,$file,$label){
  try {
    $r=Invoke-WebRequest -Uri "http://localhost:$port/" -UseBasicParsing
    $sh=(Get-FileHash -InputStream ([System.IO.MemoryStream]::new([System.Text.Encoding]::UTF8.GetBytes($r.Content))) -Algorithm MD5).Hash
    $fh=(Get-FileHash $file -Algorithm MD5).Hash
    Write-Host "$label ($port): Status=$($r.StatusCode) match_build=$($sh -eq $fh) title=$(if($r.Content -match '<title>(.*?)</title>'){$matches[1]}else{'(none)'})"
  } catch { Write-Host "$label ($port): FAILED $_" }
}
Check 8091 $new '门户H5'
Check 8092 $old '门户(原)'

$be='D:\repository\门户后端'
Write-Host "=== 门户后端 top-level ==="; Get-ChildItem $be -Depth 1 | Select-Object Name,PSIsContainer | Format-Table -AutoSize
Write-Host "=== build/config files present? ==="
foreach($f in @('package.json','pom.xml','build.gradle','application.yml','application.properties','docker-compose.yml','.env','start.sh','start.bat')){
  if(Test-Path (Join-Path $be $f)){ Write-Host "FOUND: $f" }
}
Write-Host "=== git branch/status ==="; if(Test-Path "$be\.git"){ git -C $be branch --show-current; git -C $be status --short | Select-Object -First 10 } else { 'no .git' }

$be='D:\repository\门户后端'
Write-Host "=== java ==="; try { java -version 2>&1 | Select-Object -First 3 } catch { 'NO java' }
Write-Host "=== mvn ==="; try { mvn -version 2>&1 | Select-Object -First 3 } catch { 'NO mvn' }
Write-Host "=== mvnw? ==="; if(Test-Path "$be\mvnw.cmd"){'mvnw.cmd EXISTS'} else {'no mvnw'}
Write-Host "=== target jars in server modules ==="
foreach($m in @('common-gateway','common-portal-server','common-framework-server')){
  $td=Join-Path $be "$m\target"
  if(Test-Path $td){ $j=Get-ChildItem $td -Filter *.jar -ErrorAction SilentlyContinue | Where-Object { $_.Name -notmatch 'sources|javadoc' } | Select-Object Name,LastWriteTime; Write-Host "$m/target: $(if($j){($j|ForEach-Object{$_.Name+' @ '+$_.LastWriteTime}) -join '; '}else{'no jar'})" }
}
Write-Host "=== log tails (port hints) ==="
foreach($l in @('gateway.log','portal-server.log')){
  $p=Join-Path $be $l
  if(Test-Path $p){ Write-Host "--- $l (last 5) ---"; Get-Content $p -Tail 5 }
}

Write-Host "=== listeners 8086/9222/9219 ==="
foreach($p in @(8086,9222,9219)){
  $c=Get-NetTCPConnection -LocalPort $p -ErrorAction SilentlyContinue
  if($c){ Write-Host "PORT $p : LISTENING (pid $($c.OwningProcess -join ','))" } else { Write-Host "PORT $p : not listening" }
}
Write-Host "=== java processes ==="
Get-Process java -ErrorAction SilentlyContinue | Select-Object Id,StartTime | Format-Table -AutoSize
Write-Host "=== gateway jar ==="
Get-Item 'D:\repository\门户后端\common-gateway\target\common-gateway.jar' | Select-Object Name,Length,LastWriteTime
